        transforms = ensure_list(transforms)
        if TRANSFORM_LANGUAGE_EXTENSION in transforms:
            parameters = {}
            for k, v in self._template.get("Parameters", {}).items():
                p_type = v.get("Type")
                if isinstance(p_type, str):
