            from cfnlint.rules.errors import (
                TransformError,  # pylint: disable=cyclic-import
            )

            message = "Error transforming template: {0}"
            for cause in e.causes:
                matches.append(
                    Match.create(
                        filename=self._filename,
                        rule=TransformError(),
                        message=message.format(cause.message),
                    )
